def window_sums(nums, k):
    if k <= 0:
        raise ValueError("k must be greater than 0")
    if k > len(nums):
        return []

    sums = []
    for i in range(len(nums) - k + 1):
        sums.append(sum(nums[i:i+k]))

    return sums
